{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Acarbose, a highly polar glycoside with multiple sugar units, has absolute oral bioavailability <2% in humans, directly demonstrating that this class of large hydrophilic molecules fails to reach F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Fluticasone propionate has absolute oral bioavailability of 0.91% in healthy volunteers, providing a high-transfer example of a large molecule with extensive first-pass metabolism and very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Glycyrrhizin, a glycoside with multiple polar groups, has oral bioavailability of approximately 0.25% in humans, supporting low F for large glycosylated natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Naringin, a glycoside with high polarity, has human oral bioavailability of only 5–9%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Cytarabine ocfosfate, a large polar prodrug, has systemic availability of 15.8% in patients, still below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human oral bioavailability measurements are below 20%, including acarbose (<2%), fluticasone propionate (<1%), glycyrrhizin (~0.25%), naringin (5–9%), and cytarabine ocfosfate (15.8%). The query molecule is a large, highly polar, ionizable macrolide glycoside with many H-bond donors/acceptors and rotatable bonds, consistent with these low-F compounds. No evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule.",
    "No human PK data for the specific macrolide oxime ether scaffold; extrapolation relies on high-transfer analogues.",
    "Potential role of intestinal metabolism or transporter-mediated absorption was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

